const header = (kicker, title, deck, cont=false) => `<header><span>Walton County, Florida</span><em>Fiscal Year 2027</em></header><small class="kicker">${kicker}</small><h1 class="${cont?'cont':''}">${title}</h1>${deck?`<p class="deck">${deck}</p>`:""}`;
const footer = (pageNumber = '-') => `<footer><span>FY 2027 Final Budget</span><b data-page-number>${pageNumber}</b></footer>`;
const stat = (v,l) => `<div class="stat"><b>${v}</b><span>${l}</span></div>`;
const measure = (title, vals) => `<div class="measure"><strong>${title}</strong><div class="trend">${vals.map((x,i)=>`<span class="${i===vals.length-1?'target':''}"><b>${x[0]}</b>${x[1]}</span>`).join('')}</div></div>`;

